import{_ as s,l as d,o as t,c as i,v as a,p as l,x as o,d as n,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"tty 与 PTY","description":"","frontmatter":{"title":"tty 与 PTY","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tty-pty.md","filePath":"cs/tty-pty.md","lastUpdated":1789023840000}'),h={name:"cs/tty-pty.md"};function m(T,e,_,y,E,u){const r=d("Mermaid");return t(),i("div",null,[e[1]||(e[1]=a('<h1 id="tty-与-pty" tabindex="-1">tty 与 PTY <a class="header-anchor" href="#tty-与-pty" aria-label="Permalink to &quot;tty 与 PTY&quot;">​</a></h1><div class="epigraph"><p>终端是带行规程的字符设备：规范模式处理擦除与行编辑；伪终端把同一套接口接到一对主从描述符。</p><footer>—— 据 Ritchie and Thompson；Stevens and Rago, APUE；Linux tty 文档整理</footer></div><p><a href="/cs/hrtimer">上一课</a>能做超时，shell 交互还缺「键盘与屏幕」这份文件。<a href="/cs/signals">信号</a> 的 <code>SIGINT</code> 来自终端驱动。<a href="/cs/process-image">进程组</a> 与会话（树里若已有）把前台作业接到控制终端。缺口是 <strong>tty 行规程与 PTY</strong>：不是硬件 UART 百科，而是内核对象如何把字节变成行、以及 sshd 如何用伪终端。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若把串口当原始字节管道，退格、Ctrl-C、作业控制都要每个程序自己做。Unix：行规程插在驱动与 <code>read</code> 之间——规范模式攒一行再给进程，INTR 字符变成信号。PTY：没有真实串口，master 端像「对端键盘」，slave 端对进程就是 tty。缺口是这对对象，加上 <code>TIOCSWINSZ</code> 窗口大小。</p><p>本课不把 termios 的每一位 flag 背完。</p><p><span class="marginnote">会话的控制终端接收挂断信号。后台写终端可被 <code>SIGTTOU</code> 停。本课讲机制，不写如何抢 tty 做对抗。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>真实 tty：UART 中断 → 行规程 → 等待 <code>read</code> 的进程。PTY：用户写 master → 行规程 → slave 的 <code>read</code>；进程写 slave → master 的 <code>read</code>（给仿真器画屏）。<code>open(&quot;/dev/ptmx&quot;)</code> 取得一对。窗口改变投递 <code>SIGWINCH</code>。与 <a href="/cs/vfs">VFS</a> 接头：都是字符设备 inode。</p>',9)),(t(),l(p,null,{default:o(()=>[c(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20KEY%5B%22%E9%94%AE%E7%9B%98%E6%88%96%20PTY%20master%22%5D%20--%3E%20LD%5B%22%E8%A1%8C%E8%A7%84%E7%A8%8B%22%5D%0A%20%20LD%20--%3E%20SLAVE%5B%22%E8%BF%9B%E7%A8%8B%20read%20%E4%BB%8E%20tty%22%5D%0A%20%20SLAVE%20--%3E%20OUT%5B%22%E5%86%99%E5%9B%9E%E5%B1%8F%E5%B9%95%E6%88%96%20master%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>tty 把「用户」接到进程组：中断字符是信号源，行编辑是内核里的小状态机。PTY 让网络与图形仿真器复用同一抽象，而不在内核里放 SSH 协议。不要把这写成 X11 或 Wayland 课。缓冲仍可能阻塞，select/epoll 对 tty fd 有效。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 systemd 的 getty 单元全文——init 课会接。不保证所有嵌入式没有 tty。下一课：这类驱动常常做成可加载模块，而不编进 vmlinux。</p><p>后课默认：交互式程序有 tty 语义。内核代码如何在运行时接上，下一课内核模块。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>行规程实现规范输入与终端信号。</li><li>PTY 用主从描述符仿真同一接口。</li><li>可加载驱动是模块课的缺口。</li><li>出处：Ritchie and Thompson；Stevens and Rago, <em>APUE</em>；Linux tty。</li></ul>',7))])}const S=s(h,[["render",m]]);export{P as __pageData,S as default};
